\begin{itemize}
    \item Lipid-associated
    \item MES/Glycolysis
    \item Stress/HSP
    \item MAC2, MAC3
    \item Interferon
    \item CD4/CD8 T cell subsets
    \item EMT (Epithelial-Mesenchymal Transition)
    \item Respiration
    \item Various stress responses
\end{itemize}

